        print(f"Error initializing GPIO: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

