import signal
import sys
import time

from gpiozero import PWMOutputDevice

# BCM pin numbers for the four PWM outputs
PWM_PINS = [1, 2, 3, 4]
UPDATE_INTERVAL_S = 0.1


class PWMDriver:
    """Drives PWM outputs on specified BCM pins with validation."""

    def __init__(self, pwm_pins):
        self.pwm_pins = list(pwm_pins)
        self.devices = []
        try:
            for pin in self.pwm_pins:
                dev = PWMOutputDevice(pin=pin, initial_value=0.0, frequency=100)
                self.devices.append(dev)
        except Exception as exc:
            self._cleanup()
            raise RuntimeError(f"Failed to initialize PWM devices: {exc}") from exc

    def _cleanup(self):
        for dev in getattr(self, "devices", []):
            try:
                dev.close()
            except Exception:
                pass
        self.devices.clear()

    def set_pwm_values(self, values):
        if len(values) != len(self.pwm_pins):
            raise ValueError(
                f"Expected {len(self.pwm_pins)} values, got {len(values)}"
            )
        for val in values:
            if not isinstance(val, (int, float)) or not (0 <= val <= 1):
                raise ValueError(f"PWM value {val!r} out of range [0, 1]")
        for dev, val in zip(self.devices, values):
            dev.value = float(val)

    def run(self):
        running = True

        def _signal_handler(signum, frame):
            nonlocal running
            running = False

        signal.signal(signal.SIGINT, _signal_handler)
        signal.signal(signal.SIGTERM, _signal_handler)

        try:
            while running:
                # Example valid readings — replace with sensor logic.
                pwm_values = [0.5, 0.7, 0.3, 0.9]
                try:
                    self.set_pwm_values(pwm_values)
                except ValueError as exc:
                    print(f"[WARN] Invalid PWM values: {exc}", file=sys.stderr)
                else:
                    print(f"PWM Values Set: {pwm_values}")
                time.sleep(UPDATE_INTERVAL_S)
        finally:
            self._cleanup()


if __name__ == "__main__":
    driver = PWMDriver(PWM_PINS)
    driver.run()

import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Periodically capture still images from the Raspberry Pi camera."""

    def __init__(self, interval: float = 60.0):
        self.interval = interval
        self.camera: Picamera2 | None = None
        self._running = True

    # ------------------------------------------------------------------
    # Setup / teardown
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._handle_signal)
            except (ValueError, OSError):
                pass  # not available or already handled

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}; shutting down...")
        self._running = False

    def start_camera(self) -> bool:
        """Initialise and start the camera. Return True on success."""
        try:
            self.camera = Picamera2()
            config = self.camera.create_still_configuration()
            self.camera.configure(config)
            self.camera.start()
            return True
        except Exception as exc:
            print(f"Failed to initialise/start camera: {exc}", file=sys.stderr)
            self.camera = None
            return False

    def stop_camera(self) -> None:
        """Stop and close the camera if it was opened."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception as exc:
                print(f"Warning while stopping camera: {exc}", file=sys.stderr)
            finally:
                self.camera = None

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self) -> int:
        self._install_signal_handlers()

        if not self.start_camera():
            return 1

        try:
            while self._running:
                timestamp = time.strftime("%Y%m%d-%H%M%S")
                filename = f"image_{timestamp}.jpg"
                print(f"Capturing image: {filename}")

                try:
                    self.camera.capture_file(filename)
                except Exception as exc:
                    print(f"Capture failed: {exc}", file=sys.stderr)

                # Sleep in small increments so signals are caught promptly.
                elapsed = 0.0
                while self._running and elapsed < self.interval:
                    time.sleep(0.5)
                    elapsed += 0.5

        finally:
            self.stop_camera()
            print("Camera released.")

        return 0


if __name__ == "__main__":
    app = CameraApp(interval=60.0)
    sys.exit(app.run())

