import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

# PCA9685 channel 0 maps to physical pin 13 (GPIO27) via gpiozero's default
# mapping table.  We use a dedicated PWMOutputDevice so we can enforce the
# 0.0–1.0 duty-cycle range explicitly.
CHANNEL = 0
FREQ_HZ = 200
STEP_DELAY_S = 0.05


class PCA9685Channel:
    """Thin wrapper around gpiozero.PWMOutputDevice for a single PCA9685 channel."""

    def __init__(self, channel: int = CHANNEL, freq_hz: float = FREQ_HZ):
        if not 0 <= channel <= 15:
            raise ValueError(f"PCA9685 channel {channel} out of range")
        self._device = None
        try:
            # PCA9685 channels are 4-wire digital outputs; we drive them as
            # analog-duty-cycle PWM signals via PWMOutputDevice.
            self._device = PWMOutputDevice(
                pin=channel,
                initial_value=0.0,
                frequency=freq_hz,
            )
        except GPIOZeroError as exc:
            print(f"[ERROR] Failed to initialise PCA9685 channel {channel}: {exc}", file=sys.stderr)
            raise

    @property
    def value(self) -> float:
        return self._device.value

    @value.setter
    def value(self, new_val: float):
        clamped = max(0.0, min(float(new_val), 1.0))
        self._device.value = clamped

    def close(self):
        if self._device is not None:
            try:
                self._device.close()
            finally:
                self._device = None


def main() -> int:
    pwm_channel = None
    shutting_down = False

    def _request_shutdown(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _request_shutdown)
    signal.signal(signal.SIGTERM, _request_shutdown)

    try:
        pwm_channel = PCA9685Channel()

        while not shutting_down:
            current_duty = pwm_channel.value
            print(f"Duty cycle: {current_duty:.3f}")
            time.sleep(STEP_DELAY_S)

    except GPIOZeroError as exc:
        print(f"[ERROR] GPIO failure: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"[ERROR] Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        if pwm_channel is not None:
            pwm_channel.close()
        print("Exiting cleanly.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

