            try:
                led.off()
                print(f"GPIO {OUTPUT_PIN} set LOW")
            except Exception as e:
                print(f"Error writing to GPIO {OUTPUT_PIN}: {e}", file=sys.stderr)

            if not _running:
                break

            sleep(UPDATE_INTERVAL_S)
    finally:
        try:
            led.close()
        except Exception:
            pass
        print("GPIO cleanup done.")


