    main()

import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

OUTPUT_PINS = [20, 21]
INTERVAL_SECONDS = 0.5


def read_valid_input() -> bool:
    """Read a boolean value from stdin after stripping whitespace.

    Returns True if the input was valid and accepted, False otherwise.
    """
    try:
        raw = input("Enter 1 or 0: ").strip()
    except EOFError:
        print("EOF received; exiting.")
        return False

    if not raw:
        print("Empty input; ignoring.")
        return False

    value = raw[:1].lower()
    if value == "1":
        print("Valid input: 1")
        return True
    elif value == "0":
        print("Valid input: 0")
        return False
    else:
        print(f"Invalid input '{raw}'; please enter 1 or 0.")
        return False


def main() -> int:
    outputs = []
    try:
        for pin in OUTPUT_PINS:
            out = DigitalOutputDevice(pin)
            outputs.append(out)

        while True:
            accepted = read_valid_input()
            if not accepted:
                continue

            # gpiozero uses .value property / .on()/off() for digital output.
            outputs[0].value = 1 if accepted else 0
            outputs[1].value = 0 if accepted else 1

            print(
                f"GPIO {OUTPUT_PINS[0]} set to "
                f"{outputs[0].value}, GPIO {OUTPUT_PINS[1]} set to "
                f"{outputs[1].value}"
            )

            time.sleep(INTERVAL_SECONDS)

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user; cleaning up.")
    finally:
        for out in outputs:
            try:
                out.close()
            except Exception:
                pass
        print("Cleanup done.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

