import signal
import sys
from pathlib import Path

try:
    from picamera2 import Picamera2
except ImportError as exc:
    print(f"picamera2 library not available: {exc}", file=sys.stderr)
    sys.exit(1)

IMAGE_PATH = "image.jpg"
_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def capture_image() -> bool:
    cam = None
    try:
        cam = Picamera2()
        still_config = cam.create_still_configuration()
        cam.configure(still_config)
        cam.start()

        # Brief warm-up so the first frame is not underexposed.
        for _ in range(30):
            if not _running:
                return False
            cam.wait_for_buffers(timeout=50)

        metadata = cam.capture_file(IMAGE_PATH)
        if not Path(IMAGE_PATH).is_file():
            print("Error: image was not written to disk.", file=sys.stderr)
            return False

        print(f"Image saved to {IMAGE_PATH}")
        return True

    except Exception as e:
        print(f"Camera error: {e}", file=sys.stderr)
        return False
    finally:
        if cam is not None:
            try:
                cam.stop()
            except Exception:
                pass
            try:
                cam.close()
            except Exception:
                pass


if __name__ == "__main__":
    success = capture_image()
    sys.exit(0 if success else 1)

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

TRIGGER_PIN = 17
ECHO_PIN = 22
MAX_DISTANCE_METERS = 1.0   # 1 m is well within the HC-SR04's range (~4 m typical)
SAMPLE_INTERVAL_SECONDS = 50
NUM_SAMPLES = 5


def main() -> int:
    sensor: DistanceSensor | None = None
    shutting_down = False

    def _shutdown(signum=None, frame=None):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_METERS,
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04 on TRIG={TRIGGER_PIN}, ECHO={ECHO_PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        sample_count = 0
        while sample_count < NUM_SAMPLES and not shutting_down:
            try:
                distance_meters = sensor.distance
            except DeviceClosed:
                print("Sensor device closed unexpectedly.", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Read error on cycle {sample_count + 1}/{NUM_SAMPLES}: {exc}", file=sys.stderr)
                distance_meters = -1.0

            if distance_meters >= 0:
                print(f"HC-SR04 State: {distance_meters:.3f} meters")
            else:
                print(f"HC-SR04 State: no valid reading")

            sample_count += 1
            if sample_count < NUM_SAMPLES and not shutting_down:
                time.sleep(SAMPLE_INTERVAL_SECONDS)

        if shutting_down:
            print("\nInterrupted by signal; exiting.")
        else:
            print("Sampling complete.")

    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

