import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"   # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT_S = 2.0            # Give-up timeout per read attempt
INITIAL_DELAY_S = 2.0          # Allow device time to stabilise after power-on


class SerialReader:
    """Thin wrapper around pyserial with robust open / close handling."""

    def __init__(self, port: str, baudrate: int):
        self.port = port
        self.baudrate = baudrate
        self.ser: serial.Serial | None = None

    def open(self) -> bool:
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=READ_TIMEOUT_S,
            )
            return True
        except serial.SerialException as exc:
            print(f"Error opening {self.port}: {exc}", file=sys.stderr)
            self.ser = None
            return False
        except OSError as exc:
            print(f"OS error opening {self.port}: {exc}", file=sys.stderr)
            self.ser = None
            return False

    def read_line(self) -> str | None:
        """Return one decoded line or None when no data / error."""
        if self.ser is None:
            return None
        try:
            raw = self.ser.readline()
        except serial.SerialException as exc:
            print(f"Serial read error: {exc}", file=sys.stderr)
            return None
        if not raw:
            return None
        try:
            return raw.decode("utf-8", errors="replace").strip()
        except Exception as exc:                       # pragma: no cover - defensive
            print(f"Decode error: {exc}", file=sys.stderr)
            return None

    def close(self):
        if self.ser is not None:
            try:
                self.ser.close()
            except Exception:
                pass
            finally:
                self.ser = None


def main() -> int:
    reader = SerialReader(SERIAL_PORT, BAUD_RATE)

    # Give the device a moment to initialise before we start polling.
    time.sleep(INITIAL_DELAY_S)

    if not reader.open():
        return 1

    # Non-blocking loop: read one line and print it.
    result = reader.read_line()
    if result is None:
        print("No response from device within timeout.", file=sys.stderr)
        return 1

    print(result)
    reader.close()
    return 0


def _handle_signal(signum, frame):
    raise KeyboardInterrupt


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    sys.exit(main())

