import signal
import sys
import time

from gpiozero import PWMOutputDevice

PWM_PINS = [12, 20, 21]
UPDATE_INTERVAL_S = 0.03

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin=pin, initial_value=0.0, frequency=1000)
            devices.append(dev)

        while _running:
            for i, dev in enumerate(devices):
                if i % 2 == 0:
                    dev.value = 0.5   # 50% duty cycle
                else:
                    dev.value = 0.75  # 75% duty cycle
            print(f"pwm1={devices[0].value:.1f} pwm2={devices[1].value:.1f} pwm3={devices[2].value:.1f}")
            time.sleep(UPDATE_INTERVAL_S)

    except Exception as exc:
