import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
OUT_PINS = [17, 27]
INTERVAL_S = 60


class OutputController:
    """Manage one or more digital outputs with periodic toggling."""

    def __init__(self, pins):
        self._pins = []
        try:
            for p in pins:
                dev = DigitalOutputDevice(p)
                dev.off()
                self._pins.append(dev)
        except GPIOZeroError as exc:
            # Clean up anything we already opened before re-raising.
            for dev in self._pins:
                try:
                    dev.close()
                except Exception:
                    pass
            raise RuntimeError(f"Failed to initialise GPIO {p}: {exc}") from exc

    def read_state(self, idx):
        """Return the current logical value of the indexed output."""
        dev = self._pins[idx]
        return bool(dev.value)

    def write_state(self, idx, val):
        """Drive the indexed output to *val* and confirm it changed."""
        dev = self._pins[idx]
        try:
            dev.value = bool(val)
        except DeviceClosed:
            raise RuntimeError(f"GPIO {dev.pin.number} closed unexpectedly")
        confirmed = bool(dev.value) == bool(val)
        if not confirmed:
            raise RuntimeError(
                f"GPIO {dev.pin.number} did not confirm write "
                f"(expected {val}, got {not val})"
            )
        print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] "
              f"GPIO {dev.pin.number} set to {'HIGH' if val else 'LOW'}")

    def close(self):
        """Turn everything off and release every underlying device."""
        for dev in self._pins:
            try:
                dev.off()
            except Exception:
                pass
            try:
                dev.close()
            except Exception:
                pass
        self._pins.clear()


def main():
    controller = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = OutputController(OUT_PINS)
        while not shutting_down:
            for i in range(len(OUT_PINS)):
                try:
                    controller.write_state(i, not controller.read_state(i))
                except RuntimeError as exc:
                    print(f"ERROR: {exc}", file=sys.stderr)
            if shutting_down:
                break
            # Sleep in small increments so signals are caught promptly.
            slept = 0
            while slept < INTERVAL_S and not shutting_down:
                time.sleep(1)
                slept += 1
    finally:
        if controller is not None:
            controller.close()
        print("Program terminated.")


if __name__ == "__main__":
    main()

import signal
import sys

try:
    import smbus2 as smbus
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
EXPECTED_WHO_AM_I = 0x34

running = True


def _handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def read_mpu6050(bus, addr=MPU6050_ADDR):
    """Verify the device responds by reading WHO_AM_I."""
    try:
        who = bus.read_byte_data(addr, WHO_AM_I)
    except OSError as exc:
        raise RuntimeError(f"I2C read of WHO_AM_I failed: {exc}") from exc

    if who != EXPECTED_WHO_AM_I:
        raise RuntimeError(
            f"Unexpected WHO_AM_I value 0x{who:02X} "
            f"(expected 0x{EXPECTED_WHO_AM_I:02X}). "
            "Device may be absent or not an MPU6050."
        )

    # Wake up the sensor (clear sleep bit)
    try:
        bus.write_byte_data(addr, PWR_MGMT_1, 0x00)
    except OSError as exc:
        raise RuntimeError(f"Failed to wake MPU6050: {exc}") from exc

    return addr


def main():
    bus = None
    try:
        bus = smbus.SMBus(1)  # /dev/i2c-1 on Raspberry Pi
        addr = read_mpu6050(bus)
        print(f"MPU6050 detected at 0x{addr:02X}")
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                data = bus.read_i2c_block_data(MPU6050_ADDR, 0x3B, 14)
            except OSError as exc:
                print(f"I2C read error: {exc}", file=sys.stderr)
                break

            acc_x = (data[0] << 8) | data[1]
            acc_y = (data[2] << 8) | data[3]
            acc_z = (data[4] << 8) | data[5]
            temp = (data[6] << 8) | data[7]
            gyro_x = (data[8] << 8) | data[9]
            gyro_y = (data[10] << 8) | data[11]
            gyro_z = (data[12] << 8) | data[13]

            print(
                f"acc_x={acc_x}, acc_y={acc_y}, acc_z={acc_z}, "
                f"temp={temp}, gyro_x={gyro_x}, gyro_y={gyro_y}, gyro_z={gyro_z}"
            )
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

