import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
PINS = [17, 18, 27]
INTERVAL_S = 60

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main() -> int:
    global _running

    # Register signal handlers so we can clean up on Ctrl-C or `kill`.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices: list[DigitalOutputDevice] = []
    try:
        for pin in PINS:
            dev = DigitalOutputDevice(pin)
            devices.append(dev)
            print(f"Initialized GPIO{pin} as output (initial value LOW).")

        while _running:
            for idx, dev in enumerate(devices):
                try:
                    dev.on()
                    print(f"GPIO{PINS[idx]} set HIGH")
                except DeviceClosed:
                    print(f"Warning: GPIO{PINS[idx]} was closed unexpectedly.", file=sys.stderr)
                except GPIOZeroError as exc:
                    print(f"Error writing to GPIO{PINS[idx]}: {exc}", file=sys.stderr)
            if not _running:
                break
            time.sleep(INTERVAL_S)

            for idx, dev in enumerate(devices):
                try:
                    dev.off()
                    print(f"GPIO{PINS[idx]} set LOW")
                except DeviceClosed:
                    print(f"Warning: GPIO{PINS[idx]} was closed unexpectedly.", file=sys.stderr)
                except GPIOZeroError as exc:
                    print(f"Error writing to GPIO{PINS[idx]}: {exc}", file=sys.stderr)
            if not _running:
                break
            time.sleep(INTERVAL_S)

    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        return 1
    finally:
        # Release every device we opened.
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

