            outputs.append(dev)

        while running:
            for i, dev in enumerate(outputs):
                if i % 2 == 0:
                    dev.on()
                else:
                    dev.off()

            print(f"Pins {', '.join(str(p) for p in PINS)} set "
                  f"to {[bool(d.value) for d in outputs]}")
            sleep(DELAY_SECONDS)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        # Turn everything off before releasing hardware lines
        for dev in outputs:
            try:
                dev.off()
                dev.close()
            except Exception:
                pass
