import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Periodically capture images from the Raspberry Pi camera."""

    def __init__(self, interval: float = 10.0):
        self.interval = interval
        self.camera: Picamera2 | None = None
        self._running = True

    # ------------------------------------------------------------------
    # Setup / teardown
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._handle_signal)
            except (ValueError, OSError):
                pass  # not available or already handled

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}; shutting down...")
        self._running = False

    def start_camera(self) -> bool:
        """Initialise and start the camera. Return True on success."""
        try:
            self.camera = Picamera2()
            still_config = self.camera.create_still_configuration(
                main={"size": (640, 480)}
            )
            self.camera.configure(still_config)
            self.camera.start()
            return True
        except Exception as exc:
            print(f"Failed to initialise/start camera: {exc}", file=sys.stderr)
            self.camera = None
            return False

    def stop_camera(self) -> None:
        """Stop and close the camera if it was opened."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception as exc:
                print(f"Warning while stopping camera: {exc}", file=sys.stderr)
            finally:
                self.camera = None

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self) -> int:
        self._install_signal_handlers()

        if not self.start_camera():
            return 1

        try:
            while self._running:
                timestamp = time.strftime("%Y%m%d-%H%M%S")
                filename = f"image_{timestamp}.jpg"
                try:
                    self.camera.capture_file(filename)
                    print(f"Saved: {filename}")
                except Exception as exc:
                    print(f"Capture failed: {exc}", file=sys.stderr)

                # Sleep in small increments so signals are caught promptly.
                elapsed = 0.0
                while elapsed < self.interval and self._running:
                    time.sleep(0.5)
                    elapsed += 0.5
        finally:
            self.stop_camera()

        return 0


if __name__ == "__main__":
    app = CameraApp(interval=10.0)
    sys.exit(app.run())

import signal
import sys
import time

from gpiozero import PWMOutputDevice

PWM_PINS = [4, 17, 22, 27]
INTERVAL_SECONDS = 1.0


class PwmController:
    """Manages PWM outputs on specified BCM pins."""

    def __init__(self, pin_configs):
        self.pins = []
        try:
            for cfg in pin_configs:
                dev = PWMOutputDevice(cfg)
                dev.value = 0.0
                self.pins.append(dev)
        except Exception as exc:
            self.close()
            raise RuntimeError(f"Failed to initialize PWM devices: {exc}") from exc

    def set_duty_cycle(self, index, duty_percent):
        """Set the duty cycle of a specific PWM channel.

        Args:
            index:   Channel index (0-based).
            duty_percent: Duty cycle percentage (0.0–100.0).

        Returns:
            True if the value was accepted, False otherwise.
        """
        if not 0 <= index < len(self.pins):
            print(f"Error: invalid channel index {index}", file=sys.stderr)
            return False
        if not isinstance(duty_percent, (int, float)) or not 0.0 <= duty_percent <= 100.0:
            print(f"Error: invalid duty cycle {duty_percent!r} on channel {index}", file=sys.stderr)
            return False
        try:
            self.pins[index].value = duty_percent / 100.0
            print(f"Channel {index}: {duty_percent:.1f}%")
            return True
        except Exception as exc:
            print(f"Error setting channel {index}: {exc}", file=sys.stderr)
            return False

    def close(self):
        """Release all PWM devices."""
        for dev in getattr(self, "pins", []):
            try:
                dev.close()
            except Exception:
                pass
        self.pins.clear()


def main():
    controller = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = PwmController(PWM_PINS)
        while not shutting_down:
            # Reject a reading that fails validation instead of blocking.
            if not controller.set_duty_cycle(0, 50.0):
                break
            if not controller.set_duty_cycle(1, 75.0):
                break
            if not controller.set_duty_cycle(2, 25.0):
                break
            if not controller.set_duty_cycle(3, 100.0):
                break
            time.sleep(INTERVAL_SECONDS)
    finally:
        if controller is not None:
            controller.close()
        print("Exiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

# Configuration constants
SERIAL_PORT = '/dev/serial0'   # Mini UART on Raspberry Pi 3/4/5
BAUD_RATE = 9600
TIMEOUT_S = 2.0                # Read timeout in seconds
MAX_RETRIES = 3               # Attempts per read before giving up
RETRY_DELAY_S = 0.5           # Delay between retries

# Validity ranges — replace with your sensor/device-specific limits
MIN_VALUE = -100.0
MAX_VALUE = 100.0


class SerialReader:
    """Handles serial communication with a device."""

    def __init__(self, port, baudrate, timeout):
        self.port_name = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None
        self._open()

    def _open(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port_name,
                baudrate=self.baudrate,
                timeout=self.timeout,
                write_timeout=self.timeout,
            )
            print(f"Opened {self.port_name} @ {self.baudrate} baud.")
        except serial.SerialException as e:
            print(f"Error opening serial port '{self.port_name}': {e}", file=sys.stderr)
            raise

    def close(self):
        if self.serial_connection is not None and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                print(f"Closed {self.port_name}.")
            except serial.SerialException as e:
                print(f"Warning closing serial port: {e}", file=sys.stderr)

    def read_value(self):
        """
        Reads a line from the serial port and converts it to a float.
        Returns the value or None if no valid data was received after retries.
        """
        last_error = None
        for attempt in range(MAX_RETRIES):
            try:
                raw = self.serial_connection.readline()
                if not raw:
                    # Timed out without data
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                value = float(line)
                if MIN_VALUE <= value <= MAX_VALUE:
                    return value
                else:
                    print(f"Invalid value ({value}) outside expected range "
                          f"[{MIN_VALUE}, {MAX_VALUE}]. Skipping.", file=sys.stderr)
                    return None

            except ValueError:
                print(f"Could not convert data to float: '{line}'.", file=sys.stderr)
                last_error = "ValueError"
            except serial.SerialException as e:
                print(f"Serial I/O error during read: {e}", file=sys.stderr)
                last_error = str(e)
            except Exception as e:
                print(f"Unexpected error reading from serial port: {e}", file=sys.stderr)
                last_error = str(e)

            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY_S)

        print(f"Gave up after {MAX_RETRIES} attempts. Last error: {last_error}",
              file=sys.stderr)
        return None


def main():
    reader = None
    shutting_down = False

    def signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True
        print(f"\nReceived signal {signum}, exiting gracefully...")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        reader = SerialReader(SERIAL_PORT, BAUD_RATE, TIMEOUT_S)
        while not shutting_down:
            value = reader.read_value()
            if value is not None:
                print(f"Reading: {value}")
            if shutting_down:
                break
            time.sleep(0.1)

    except serial.SerialException:
        print("Fatal: Could not open serial port. Is /dev/serial0 connected?",
              file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Fatal unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if reader is not None:
            reader.close()


if __name__ == "__main__":
    main()

