import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
PINS = [17, 27]
INTERVAL_S = 0.1


def main() -> int:
    devices: list[DigitalOutputDevice] = []
    try:
        for pin in PINS:
            dev = DigitalOutputDevice(pin)
            devices.append(dev)

        # Drive HIGH initially per spec.
        for dev in devices:
            dev.on()

        print(f"Initialized {len(PINS)} output(s): {[d.pin.number for d in devices]}")
        print("State reported every %.1fs. Press Ctrl+C to stop." % INTERVAL_S)

        while True:
            for dev in devices:
                state = "HIGH" if dev.value else "LOW"
                print(f"GPIO{dev.pin.number}: {state}")
            time.sleep(INTERVAL_S)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
        return 0
    except (GPIOZeroError, DeviceClosed) as exc:
        print(f"Hardware error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
