import signal
import sys
import time

from gpiozero import DigitalOutputDevice

OUTPUT_PINS = [17, 22]
INTERVAL_SECONDS = 0.5


def validate_reading(reading: int) -> bool:
    """Return True if *reading* is a valid digital-output value."""
    return isinstance(reading, int) and reading in (0, 1)


def main() -> None:
    outputs = []
    try:
        for pin in OUTPUT_PINS:
            out = DigitalOutputDevice(pin)
            outputs.append(out)

        def cleanup(signum=None, frame=None):
            for out in outputs:
                try:
                    out.close()
                except Exception:
                    pass
            if signum is not None:
                print(f"\nReceived signal {signum}; exiting.", file=sys.stderr)
                sys.exit(0)

        signal.signal(signal.SIGINT, cleanup)
        signal.signal(signal.SIGTERM, cleanup)

        while True:
            readings = [int(i % 2) for i in range(len(outputs))]
            for out, val in zip(outputs, readings):
                if validate_reading(val):
                    out.value = val
                    print(f"GPIO{out.pin.number} set to {val}")
                else:
                    print(
                        f"Invalid reading {val!r} for GPIO{out.pin.number}",
                        file=sys.stderr,
                    )
            time.sleep(INTERVAL_SECONDS)

    except KeyboardInterrupt:
        pass
    finally:
        for out in outputs:
            try:
                out.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
QMC5883L_ADDR = 0x0D
REG_DATA_X_LSB = 0x00
NUM_READINGS = 3
DELAY_SECONDS = 0.1


class Qmc5883lReader:
    def __init__(self, bus_num=I2C_BUS):
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as exc:
            raise RuntimeError(f"Cannot open I2C bus {bus_num}: {exc}") from exc

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            finally:
                self.bus = None

    @staticmethod
    def _read_axis(bus, reg_lsb):
        write_msg = i2c_msg.write(QMC5883L_ADDR, [reg_lsb])
        read_msg = i2c_msg.read(QMC5883L_ADDR, 2)
        bus.i2c_rdwr(write_msg, read_msg)
        raw = list(read_msg)
        return (raw[0] | (raw[1] << 8)) & 0xFFFF

    def read_once(self):
        x = self._read_axis(self.bus, REG_DATA_X_LSB)
        y = self._read_axis(self.bus, REG_DATA_X_LSB + 2)
        z = self._read_axis(self.bus, REG_DATA_X_LSB + 4)
        return x, y, z


def main():
    reader = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        reader = Qmc5883lReader()

        for i in range(NUM_READINGS):
            if shutting_down:
                break
            try:
                x, y, z = reader.read_once()
            except OSError as exc:
                print(f"[ERROR] Read failed on sample {i + 1}/{NUM_READINGS}: {exc}", file=sys.stderr)
                continue
            print(f"Sample {i + 1}/{NUM_READINGS} -> X: {x}, Y: {y}, Z: {z}")
            if i < NUM_READINGS - 1:
                time.sleep(DELAY_SECONDS)

    except RuntimeError as exc:
        print(f"[FATAL] Initialization error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"[FATAL] Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if reader is not None:
            reader.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Continuously capture images from the Raspberry Pi camera every 5 s."""

    def __init__(self):
        self.camera = None
        self._running = True

    # ------------------------------------------------------------------
    # Setup / teardown
    # ------------------------------------------------------------------
    def _install_signal_handlers(self):
        """Graceful shutdown on SIGINT / SIGTERM."""
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._handle_signal)
            except (ValueError, OSError):
                pass  # not available or not our process group

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}; shutting down...")
        self._running = False

    def setup_camera(self):
        """Initialise the Picamera2 instance; return True on success."""
        try:
            self.camera = Picamera2()
            still_config = self.camera.create_still_configuration(
                main={"size": (1920, 1080)}
            )
            self.camera.configure(still_config)
            self.camera.start()
            print("Camera initialised successfully.")
            return True
        except Exception as exc:
            print(f"Failed to initialise camera: {exc}", file=sys.stderr)
            self.camera = None
            return False

    def cleanup(self):
        """Release camera resources safely."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
            finally:
                self.camera = None
        print("Resources released.")

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self):
        self._install_signal_handlers()

        if not self.setup_camera():
            self.cleanup()
            sys.exit(1)

        try:
            while self._running:
                timestamp = int(time.time() * 1000)
                filename = f"image_{timestamp}.jpg"
                print(f"Capturing image: {filename}")

                try:
                    self.camera.capture_file(filename)
                except Exception as exc:
                    print(f"Capture failed: {exc}", file=sys.stderr)

                # Sleep in small increments so signals are caught promptly.
                slept = 0
                while slept < 5 and self._running:
                    time.sleep(0.1)
                    slept += 0.1
        finally:
            self.cleanup()


if __name__ == "__main__":
    app = CameraApp()
    app.run()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
PCA9685_ADDR = 0x40
READ_INTERVAL_S = 0.15


class PCATester:
    def __init__(self, bus_num: int, addr: int):
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as exc:
            raise RuntimeError(f"Failed to open I2C bus {bus_num}: {exc}") from exc

    def read_channel(self, channel: int) -> float | None:
        """Read one PWM channel value from the PCA9685.

        Returns the raw 12-bit value (0-4095) or None if the read fails.
        """
        if not 0 <= channel <= 15:
            print(f"Invalid channel index: {channel}", file=sys.stderr)
            return None

        # Read 2 bytes from the two register addresses for this channel.
        reg = 0x00 + (channel * 4)
        try:
            write_msg = i2c_msg.write(self.addr, [reg])
            read_msg = i2c_msg.read(self.addr, 2)
            self.bus.i2c_rdwr(write_msg, read_msg)
            data = list(read_msg)
        except OSError as exc:
            print(f"I2C read error on channel {channel}: {exc}", file=sys.stderr)
            return None

        if len(data) < 2:
            print(f"Incomplete read on channel {channel} ({len(data)} bytes)", file=sys.stderr)
            return None

        raw = (data[0] << 8) | data[1]
        if not 0 <= raw <= 4095:
            print(f"Channel {channel} value out of range: {raw}", file=sys.stderr)
            return None

        return raw

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            finally:
                self.bus = None


def main():
    tester = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        tester = PCATester(I2C_BUS, PCA9685_ADDR)
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while not shutting_down:
            val = tester.read_channel(0)
            if val is not None:
                print(val)
            else:
                print("No valid reading", file=sys.stderr)
            time.sleep(READ_INTERVAL_S)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if tester is not None:
            tester.close()


if __name__ == "__main__":
    main()

