import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
INA219_ADDR = 0x1D
READ_INTERVAL_S = 1.0
NUM_READINGS = 5


class INA219Reader:
    """Minimal driver for the TI INA219 current/shunt monitor."""

    def __init__(self, bus: int, addr: int):
        self.bus_num = bus
        self.addr = addr
        self._bus: SMBus | None = None

    def open(self) -> bool:
        try:
            self._bus = SMBus(self.bus_num)
        except OSError as exc:
            print(f"Error opening I2C bus {self.bus_num}: {exc}", file=sys.stderr)
            return False
        # Probe the device with a zero-length write.
        try:
            msg = i2c_msg.write(self.addr, [])
            self._bus.i2c_rdwr(msg)
        except OSError as exc:
            print(
                f"No INA219 found at 0x{self.addr:02X} on bus {self.bus_num}: {exc}",
                file=sys.stderr,
            )
            self.close()
            return False
        return True

    def close(self) -> None:
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            finally:
                self._bus = None

    @staticmethod
    def _read_reg(bus: SMBus, reg: int) -> int:
        write_msg = i2c_msg.write(INA219_ADDR, [reg])
        read_msg = i2c_msg.read(INA219_ADDR, 2)
        bus.i2c_rdwr(write_msg, read_msg)
        raw = bytes(read_msg)
        return (raw[0] << 8) | raw[1]

    def read_current_mA(self) -> float:
        """Return signed current in milliamps."""
        raw = self._read_reg(self._bus, 0x04)
        if raw & 0x8000:
            raw -= 1 << 16
        return raw * 0.1


def main() -> int:
    reader = INA219Reader(I2C_BUS, INA219_ADDR)

    def _signal_handler(signum, frame):
        raise KeyboardInterrupt

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not reader.open():
        return 1

    try:
        for i in range(NUM_READINGS):
            try:
                current = reader.read_current_mA()
            except OSError as exc:
                print(f"I2C read error on sample {i + 1}/{NUM_READINGS}: {exc}", file=sys.stderr)
                return 1
            print(f"Sample {i + 1}/{NUM_READINGS}: Current = {current:.3f} mA")
            if i < NUM_READINGS - 1:
                time.sleep(READ_INTERVAL_S)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        return 130
    finally:
        reader.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

