import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = '/dev/serial0'   # Mini UART on Raspberry Pi 3/4/5
BAUD_RATE = 9600
READ_TIMEOUT_S = 2.0            # Non-blocking-ish read window
INITIAL_DELAY_S = 0.5           # Give the device time to stabilise after open

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=READ_TIMEOUT_S,
            )
        except serial.SerialException as exc:
            print(f"Error opening {SERIAL_PORT}: {exc}", file=sys.stderr)
            return 1

        time.sleep(INITIAL_DELAY_S)  # Allow module to initialise / warm up

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('utf-8', errors='replace').strip()
            if line:
                print(line)

    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except Exception:
                pass

    return 0


