import time
import signal
import sys

from picamera2 import Picamera2


class CameraController:
    """Manages the Raspberry Pi camera lifecycle and image capture."""

    def __init__(self):
        self.camera = None
        self._running = True

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def start(self):
        """Initialize and start the Picamera2 instance."""
        try:
            self.camera = Picamera2()
            still_config = self.camera.create_still_configuration(
                main={"size": (640, 480)}
            )
            self.camera.configure(still_config)
            self.camera.start()
            return True
        except Exception as e:
            print(f"Error initializing camera: {e}")
            self.camera = None
            return False

    def stop(self):
        """Stop and close the camera safely."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception as e:
                print(f"Warning during camera stop: {e}")
            finally:
                self.camera = None

    def capture_image(self, filename="image.jpg"):
        """Capture a single image and save it to disk.

        Returns True on success, False on failure.
        """
        if self.camera is None:
            print("Camera not initialized.")
            return False

        try:
            # Capture array first to validate the sensor is alive
            arr = self.camera.capture_array()
            if arr is None or arr.size == 0:
                print("Failed to capture valid image data.")
                return False

            self.camera.capture_file(filename)
            print(f"Image saved to {filename}")
            return True
        except Exception as e:
            print(f"Error capturing image: {e}")
            return False


def run_capture_cycle(controller, cycle_index):
    """Run a single capture cycle and sleep between them."""
    print(f"--- Cycle {cycle_index + 1} ---")
    ok = controller.capture_image(f"image_{cycle_index}.jpg")
    if not ok:
        print(f"Cycle {cycle_index + 1}: capture failed.")


def main():
    signal.signal(signal.SIGINT, signal.SIG_IGN)  # Let handler manage signals
    signal.signal(signal.SIGTERM, signal.SIG_IGN)

    controller = CameraController()

    # Register signal handlers after ignoring defaults so we can catch Ctrl-C
    signal.signal(signal.SIGINT, controller._handle_signal)
    signal.signal(signal.SIGTERM, controller._handle_signal)

    if not controller.start():
        sys.exit(1)

    try:
        for i in range(3):
            if not controller._running:
                break
            run_capture_cycle(controller, i)
            if i < 2 and controller._running:
                time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
