import signal
import sys
import time

from gpiozero import PWMOutputDevice

PWM_PINS = [12, 13, 18, 19, 22, 23]
INTERVAL_SECONDS = 2.0


class PwmController:
    """Manages PWM outputs on specified BCM pins."""

    def __init__(self, pin_configs):
        self.pins = []
        try:
            for cfg in pin_configs:
                dev = PWMOutputDevice(cfg)
                dev.value = 0.0
                self.pins.append(dev)
        except Exception as exc:
            self.close()
            raise RuntimeError(f"Failed to initialize PWM devices: {exc}") from exc

    def set_duty_cycle(self, index, duty_percent):
        if not 0 <= index < len(self.pins):
            print(f"Error: invalid pin index {index}", file=sys.stderr)
            return False
        if not isinstance(duty_percent, (int, float)) or not 0 <= duty_percent <= 100:
            print(f"Error: invalid duty cycle {duty_percent!r} for pin {PWM_PINS[index]}", file=sys.stderr)
            return False
        try:
            self.pins[index].value = duty_percent / 100.0
            print(f"Pin {PWM_PINS[index]} -> {duty_percent}%")
            return True
        except Exception as exc:
            print(f"Error setting pin {PWM_PINS[index]}: {exc}", file=sys.stderr)
            return False

    def close(self):
        for dev in getattr(self, "pins", []):
            try:
                dev.close()
            except Exception:
                pass
        self.pins.clear()


def main():
    controller = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = PwmController(PWM_PINS)
        while not shutting_down:
            for i in range(len(PWM_PINS)):
                if shutting_down:
                    break
                ok = controller.set_duty_cycle(i, 50)
                if not ok:
                    print("Aborting loop due to error.", file=sys.stderr)
                    break
            if shutting_down:
                break
            time.sleep(INTERVAL_SECONDS)
    finally:
        if controller is not None:
            controller.close()
        print("\nExiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
EXPECTED_WHO_AM_I = 0x68

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def read_mpu6050(bus: SMBus) -> None:
    """Read a single byte from WHO_AM_I and print it."""
    try:
        who_am_i = bus.read_byte_data(MPU6050_ADDR, WHO_AM_I)
    except OSError as exc:
        print(f"Error: failed to communicate with MPU6050 at 0x{MPU6050_ADDR:02X}: {exc}", file=sys.stderr)
        return

    if who_am_i != EXPECTED_WHO_AM_I:
        print(
            f"Warning: WHO_AM_I mismatch — got 0x{who_am_i:02X}, "
            f"expected 0x{EXPECTED_WHO_AM_I:02X}. Device may not be an MPU6050.",
            file=sys.stderr,
        )
        return

    # Wake up the sensor (clear sleep bit).
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
    except OSError as exc:
        print(f"Warning: could not wake MPU6050: {exc}", file=sys.stderr)

    while running:
        try:
            data = bus.read_byte_data(MPU6050_ADDR, WHO_AM_I)
        except OSError as exc:
            print(f"Error: I2C read failed: {exc}", file=sys.stderr)
            break
        print(data)
        time.sleep(0.1)


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except FileNotFoundError:
        print("Error: /dev/i2c-1 not found. Enable I2C via raspi-config.", file=sys.stderr)
        return 1
    except PermissionError:
        print("Error: permission denied opening /dev/i2c-1. Run as root or add user to 'i2c' group.", file=sys.stderr)
        return 1)
    except Exception as exc:
        print(f"Error: cannot open I2C bus: {exc}", file=sys.stderr)
        return 1

    try:
        read_mpu6050(bus)
    finally:
        bus.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Continuously capture images from the Raspberry Pi camera."""

    def __init__(self):
        self.camera = None
        self._running = True

    # ------------------------------------------------------------------
    # Setup / teardown
    # ------------------------------------------------------------------
    def setup(self) -> bool:
        """Initialise the camera. Returns False if the device is absent."""
        try:
            self.camera = Picamera2()
            still_config = self.camera.create_still_configuration(
                main={"size": (640, 480)}
            )
            self.camera.configure(still_config)
            self.camera.start()
            return True
        except Exception as exc:
            print(f"[ERROR] Failed to initialise camera: {exc}", file=sys.stderr)
            self.camera = None
            return False

    def cleanup(self) -> None:
        """Release the camera resource safely."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception as exc:
                print(f"[WARN] Error stopping camera: {exc}", file=sys.stderr)
            finally:
                self.camera = None

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self) -> int:
        """Run the capture loop. Returns process exit code."""
        if not self.setup():
            return 1

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            while self._running:
                self.capture_image()
                time.sleep(0.1)
        except Exception as exc:
            print(f"[ERROR] Unexpected exception in main loop: {exc}", file=sys.stderr)
            return 1
        finally:
            self.cleanup()

        return 0

    def _signal_handler(self, signum, frame) -> None:
        """Set the running flag to False so the loop exits cleanly."""
        self._running = False

    def capture_image(self) -> None:
        """Capture one image and save it to disk.

        Skips the sample if the device is not ready or the read fails.
        """
        if self.camera is None:
            print("[WARN] Camera not initialised — skipping capture.", file=sys.stderr)
            return

        try:
            metadata = self.camera.capture_file("image.jpg")
            if metadata is None:
                print("[WARN] Capture returned no metadata.", file=sys.stderr)
                return
            print(f"Image saved successfully (metadata={metadata}).")
        except Exception as exc:
            print(f"[ERROR] Failed to capture/save image: {exc}", file=sys.stderr)


if __name__ == "__main__":
    app = CameraApp()
    sys.exit(app.run())

