def read_sensor(sensor, pin_name):
    try:
        temp = sensor.temperature
        hum = sensor.humidity
        if temp is None or hum is None:
            return f"{pin_name}: ERROR (no data)"
        return f"{pin_name}: T={temp:.1f}C H={hum:.1f}%"
    except RuntimeError as e:
        return f"{pin_name}: ERROR ({e})"
    except Exception as e:
        return f"{pin_name}: ERROR ({e})"


