import signal
import sys
import time

import serial

# Configuration constants
SERIAL_PORT = '/dev/serial0'   # Mini UART on Raspberry Pi GPIO 14/15
BAUD_RATE = 9600
TIMEOUT_S = 1.0                # Read timeout per attempt
POLL_INTERVAL_S = 0.5         # Delay between successful reads


class SensorReader:
    """Reads sensor data from a serial port with validation and cleanup."""

    def __init__(self, port: str, baudrate: int):
        self.port_name = port
        self.baudrate = baudrate
        self.serial_connection: serial.Serial | None = None
        self._open()

    # ------------------------------------------------------------------
    # Lifecycle
    # ------------------------------------------------------------------
    def _open(self) -> None:
        try:
            self.serial_connection = serial.Serial(
                port=self.port_name,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=TIMEOUT_S,
            )
        except serial.SerialException as exc:
            print(f"Error opening {self.port_name}: {exc}", file=sys.stderr)
            raise

    def close(self) -> None:
        if self.serial_connection is not None:
            try:
                if self.serial_connection.is_open:
                    self.serial_connection.reset_input_buffer()
                    self.serial_connection.close()
            except Exception as exc:                       # noqa: BLE001
                print(f"Warning closing {self.port_name}: {exc}", file=sys.stderr)
            finally:
                self.serial_connection = None

    # ------------------------------------------------------------------
    # Reading
    # ------------------------------------------------------------------
    def read_data(self) -> str | None:
        """
        Attempt one line of data.

        Returns the stripped string, or ``None`` when no data is available
        within the timeout window.
        """
        if self.serial_connection is None or not self.serial_connection.is_open:
            return None

        try:
            raw = self.serial_connection.readline()          # blocks <= TIMEOUT_S
        except serial.SerialException as exc:
            print(f"Serial read error: {exc}", file=sys.stderr)
            return None

        if not raw:
            return None

        text = raw.decode('ascii', errors='replace').strip()
        if not text:
            return None

        # Basic plausibility guard — reject empty / whitespace-only frames
        if not text.strip():
            return None

        return text

    @staticmethod
    def validate_reading(reading: str) -> bool:
        """Return True if *reading* appears to be a valid numeric payload."""
        return bool(reading and any(c.isdigit() for c in reading))


def main() -> int:
    reader = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        reader = SensorReader(SERIAL_PORT, BAUD_RATE)
    except Exception:
        print("Failed to initialize serial communication.", file=sys.stderr)
        return 1

    try:
        while not shutting_down:
            reading = reader.read_data()
            if reading is None:
                # No data within the timeout window — loop and retry.
                continue

            if SensorReader.validate_reading(reading):
                print(f"Sensor Data: {reading}")
            else:
                print(f"Invalid reading rejected: {reading!r}")

            time.sleep(POLL_INTERVAL_S)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
        return 1
    finally:
        reader.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

# Configuration
SERIAL_PORT = '/dev/serial0'   # Primary UART on Raspberry Pi (GPIO 14/15)
BAUD_RATE = 9600
TIMEOUT_S = 1.0                # Read timeout in seconds
POLL_INTERVAL_S = 1.0         # Delay between successful reads

_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def read_serial_data(ser):
    """
    Reads a line of data from the serial port.
    Returns the decoded string, or None if no data / error occurs.
    """
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"I/O error during serial read: {e}", file=sys.stderr)
        return None


def process_reading(data):
    """Prints the received data to the console."""
    if data:
        print(f'Received: {data}')


def main():
    """Main function to continuously read and display sensor data."""
    global _running

    # Register signal handlers for clean termination
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        # Initialize serial connection
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                timeout=TIMEOUT_S,
                write_timeout=TIMEOUT_S
            )
        except serial.SerialException as e:
            print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
            sys.exit(1)

        print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud...")

        while _running:
            data = read_serial_data(ser)
            if data is not None:
                process_reading(data)
            else:
                # No data or transient error — wait before retrying instead of blocking forever
                pass

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < POLL_INTERVAL_S:
                time.sleep(0.1)
                slept += 0.1

    finally:
        # Ensure serial port is closed on exit
        if ser is not None and ser.is_open:
            try:
                ser.close()
                print("\nSerial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
INA219_ADDR = 0x40
READ_INTERVAL_S = 1.0
NUM_READINGS = 60


class INA219Reader:
    """Minimal driver for the TI INA219 current/shunt monitor."""

    def __init__(self, bus: int, addr: int):
        self.bus_num = bus
        self.addr = addr
        self._bus: SMBus | None = None

    def open(self) -> None:
        try:
            self._bus = SMBus(self.bus_num)
        except OSError as exc:
            raise RuntimeError(f"Cannot open I2C bus {self.bus_num}: {exc}") from exc

    def close(self) -> None:
        if self._bus is not None:
            try:
                self._bus.close()
            finally:
                self._bus = None

    @staticmethod
    def _read_reg(bus: SMBus, reg: int) -> int:
        write_msg = i2c_msg.write(INA219_ADDR, [reg])
        read_msg = i2c_msg.read(INA219_ADDR, 2)
        bus.i2c_rdwr(write_msg, read_msg)
        raw = bytes(read_msg)
        return (raw[0] << 8) | raw[1]

    def read_current_mA(self) -> float:
        """Return signed current in milliamps."""
        raw = self._read_reg(self._bus, 0x01)  # SHUNT_VOLTAGE register
        if raw & 0x8000:
            raw -= 1 << 15
        return raw * 0.1


def main() -> int:
    reader = INA219Reader(I2C_BUS, INA219_ADDR)

    # Verify the device responds before starting.
    try:
        reader.open()
    except RuntimeError as exc:
        print(f"[ERROR] {exc}", file=sys.stderr)
        return 1

    try:
        for i in range(NUM_READINGS):
            try:
                current_ma = reader.read_current_mA()
            except OSError as exc:
                print(f"[ERROR] I2C read failed on sample {i + 1}/{NUM_READINGS}: {exc}", file=sys.stderr)
                return 1
            print(f"Sample {i + 1}/{NUM_READINGS} - Current: {current_ma:.3f} mA")
            time.sleep(READ_INTERVAL_S)
    finally:
        reader.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

