import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

TRIGGER_PIN = 25
SAMPLE_PERIOD_S = 0.5
MAX_DISTANCE_M = 1.0  # 1 m is well within the HC-SR04's 4 m range


def main() -> int:
    sensor: DistanceSensor | None = None
    shutting_down = False

    def _request_shutdown(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _request_shutdown)
    signal.signal(signal.SIGTERM, _request_shutdown)

    try:
        sensor = DistanceSensor(
            echo=TRIGGER_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_M,
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04 on BCM {TRIGGER_PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        while not shutting_down:
            try:
                distance_m = sensor.distance
            except DeviceClosed:
                print("Sensor device closed unexpectedly.", file=sys.stderr)
                break
            except Exception as exc:  # noqa: BLE001 - log and continue
                print(f"Read error: {exc}", file=sys.stderr)
                distance_m = None

            if distance_m is not None:
                print(f"HC-SR04 State: {distance_m:.3f} meters")
            else:
                print("HC-SR04 State: read unavailable")

            time.sleep(SAMPLE_PERIOD_S)
    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:  # noqa: BLE001
                pass

    return 0


if __name__ == "__main__":
