PIN_MAP = {
    4: board.D4,
    17: board.D17,
    27: board.D27,
}

running = True


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)


def read_sensor(sensor):
    """Read temperature and humidity from a DHT22 sensor.

    Returns (temperature_c, humidity_percent) or None on failure.
    """
    try:
        temp = sensor.temperature
        hum = sensor.humidity
        if temp is not None and hum is not None:
            return temp, hum
    except RuntimeError as e:
        # Common transient errors: checksum mismatch, timeout, etc.
        pass
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}", file=sys.stderr)
    return None


def main():
    sensors = {}
    try:
        for bcm_pin in [4, 17, 27]:
            try:
                sensors[bcm_pin] = adafruit_dht.DHT22(PIN_MAP[bcm_pin], use_pulseio=False)
            except Exception as e:
                print(f"Failed to initialize DHT22 on BCM GPIO{bcm_pin}: {e}",
                      file=sys.stderr)
                sys.exit(1)

        while running:
            results = []
            for bcm_pin, sensor in sensors.items():
                data = read_sensor(sensor)
                if data is not None:
                    temp, hum = data
                    results.append((bcm_pin, f"{temp:.1f}C", f"{hum:.1f}%"))
                else:
                    results.append((bcm_pin, "ERROR", "ERROR"))

