import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

# Configuration
SERIAL_PORT = '/dev/serial0'   # Primary UART on Raspberry Pi (GPIO 14/15)
BAUD_RATE = 9600
TIMEOUT_S = 1.0                # Read timeout in seconds
POLL_INTERVAL_S = 0.5         # Delay between successful reads

_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def read_sensor_data(ser):
    """
    Reads a line of text from the serial port.
    Returns the decoded string, or None if no data / timeout occurs.
    """
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"I/O error during serial read: {e}", file=sys.stderr)
        return None


def process_reading(reading):
    """Prints the sensor reading to standard output."""
    if reading:
        print(f'Sensor Reading: {reading}')


def main():
    """Main function to continuously read and display sensor data."""
    global _running

    # Register signal handlers for clean termination
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        # Initialize serial connection
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                timeout=TIMEOUT_S,
                write_timeout=TIMEOUT_S
            )
        except serial.SerialException as e:
            print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
            sys.exit(1)

        print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud...")

        while _running:
            data = read_sensor_data(ser)
            if data is not None:
                process_reading(data)
            else:
                # No data received within timeout window — skip sleep to avoid 1-second gap
                pass

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < POLL_INTERVAL_S:
                time.sleep(0.05)
                slept += 0.05

    finally:
        # Clean resource release on all exit paths
        if ser is not None and ser.is_open:
            try:
                ser.close()
                print("\nSerial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)


if __name__ == "__main__":
    main()

import time
import signal
import sys

try:
    import board
    import adafruit_dht
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-dht", file=sys.stderr)
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D22          # BCM GPIO 22 (physical pin 15)
READ_INTERVAL_S = 3          # Delay between successful readings
MAX_RETRIES = 3              # Attempts per cycle before giving up on this sample

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def read_sensor(sensor):
    """
    Attempt a single reading from the DHT22.
    Returns (humidity_pct, temperature_c) or None if the reading is invalid.
    Retries MAX_RETRIES times to cope with transient timing glitches.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            humidity = sensor.humidity
            temperature = sensor.temperature

            # CircuitPython DHT can return None when the sensor is absent or busy.
            if humidity is None or temperature is None:
                raise RuntimeError("Sensor returned None")

            # Sanity-range checks (DHT22 operational range)
            if not (-40.0 <= temperature <= 80.0):
                raise ValueError(f"Temperature out of range: {temperature}")
            if not (0.0 <= humidity <= 100.0):
                raise ValueError(f"Humidity out of range: {humidity}")

            return humidity, temperature

        except Exception as e:
            print(
                f"Reading failed (attempt {attempt}/{MAX_RETRIES}): {e}",
                file=sys.stderr,
            )
            if attempt < MAX_RETRIES:
                time.sleep(0.5)

    return None


def main():
    """Run two sampling cycles, one every READ_INTERVAL_S seconds."""
    sensor = None
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        print("DHT22 initialized on GPIO 22.")

        for cycle in range(1, 3):
            if not _running:
                break

            result = read_sensor(sensor)
            if result is not None:
                humidity, temperature = result
                print(
                    f"[Cycle {cycle}/2] Humidity: {humidity:.1f} %  "
                    f"Temperature: {temperature:.1f} °C"
                )
            else:
                print(
                    f"[Cycle {cycle}/2] Failed to obtain valid reading after "
                    f"{MAX_RETRIES} attempts.",
                    file=sys.stderr,
                )

            if cycle < 2 and _running:
                time.sleep(READ_INTERVAL_S)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)

    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus

I2C_BUS = 1
BMP280_ADDR = 0x76
REG_CTRL_MEAS = 0xF4
REG_PRESS_MSB = 0xF7
REG_TEMP_MSB = 0xFA
CTRL_MEAS_VAL = 0x27  # osrs_t=1, osrs_p=1, mode=normal -> ~5.5 ms conversion
READ_INTERVAL_S = 1.0
NUM_READINGS = 2


class BMP280Reader:
    def __init__(self, bus_num: int, addr: int):
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as exc:
            raise RuntimeError(f"Cannot open I2C bus {bus_num}: {exc}") from exc

    def close(self) -> None:
        if self.bus is not None:
            try:
                self.bus.close()
            finally:
                self.bus = None

    @staticmethod
    def _read_reg(bus, reg: int, length: int) -> bytes:
        return bytes(bus.read_i2c_block_data(BMP280_ADDR, reg, length))

    def read(self) -> float | None:
        """Read pressure in hPa from the BMP280.

        Returns None when the device is absent or data is invalid.
        """
        try:
            ctrl_meas = self._read_reg(self.bus, REG_CTRL_MEAS, 1)
            if len(ctrl_meas) < 1:
                print("Error: CTRL_MEAS register returned no data", file=sys.stderr)
                return None
            self.bus.write_byte_data(self.addr, REG_CTRL_MEAS, CTRL_MEAS_VAL)

            deadline = time.monotonic() + 0.01
            while True:
                status = self._read_reg(self.bus, REG_CTRL_MEAS, 1)
                if len(status) >= 1 and (status[0] & 0x03) == 0:
                    break
                if time.monotonic() > deadline:
                    print("Warning: BMP280 conversion timed out", file=sys.stderr)
                    return None
                time.sleep(0.005)

            press_data = self._read_reg(self.bus, REG_PRESS_MSB, 3)
            temp_data = self._read_reg(self.bus, REG_TEMP_MSB, 3)

            if len(press_data) != 3 or len(temp_data) != 3:
                print("Error: incomplete sensor data", file=sys.stderr)
                return None

            raw_press = (press_data[0] << 12) | (press_data[1] << 4) | (press_data[2] >> 4)
            raw_temp = (temp_data[0] << 12) | (temp_data[1] << 4) | (temp_data[2] >> 4)

            # Validate range per datasheet: P in [30_000, 110_000], T in [3_000, 32_767]
            if not (30_000 <= raw_press <= 110_000):
                print(f"Warning: pressure out of range: {raw_press}", file=sys.stderr)
                return None
            if not (3_000 <= raw_temp <= 32_767):
                print(f"Warning: temperature out of range: {raw_temp}", file=sys.stderr)
                return None

            # Simplified compensation: scale to hPa assuming sea-level pressure calibration
            # For production use, implement full Bosch compensation (dig_T/P_* tables).
            pressure_hpa = raw_press / 256.0
            return round(pressure_hpa, 2)

        except OSError as exc:
            print(f"I2C communication error: {exc}", file=sys.stderr)
            return None


def main() -> int:
    reader = None
    try:
        reader = BMP280Reader(I2C_BUS, BMP280_ADDR)
    except RuntimeError as exc:
        print(exc, file=sys.stderr)
        return 1

    def shutdown(signum=None, frame=None):
        if reader is not None:
            reader.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)

    try:
        for i in range(NUM_READINGS):
            value = reader.read()
            if value is not None:
                print(f"[{i+1}/{NUM_READINGS}] Pressure: {value} hPa")
            else:
                print(f"[{i+1}/{NUM_READINGS}] Reading failed", file=sys.stderr)
            if i < NUM_READINGS - 1:
                time.sleep(READ_INTERVAL_S)
    finally:
        reader.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
OUTLET_1_PIN = 17
OUTLET_2_PIN = 18
POLL_INTERVAL_S = 5


class SmartOutletsController:
    """Controls two digital outputs on a Raspberry Pi with validation."""

    def __init__(self, outlet1_pin: int, outlet2_pin: int):
        self.outlet1 = None
        self.outlet2 = None
        try:
            self.outlet1 = DigitalOutputDevice(outlet1_pin)
            self.outlet2 = DigitalOutputDevice(outlet2_pin)
        except GPIOZeroError as exc:
            print(f"Failed to initialize GPIO pins {outlet1_pin}/{outlet2_pin}: {exc}", file=sys.stderr)
            raise

    def set_outlet_state(self, outlet_number: int, state: bool) -> bool:
        """Set an outlet to ON (True) or OFF (False). Returns True on success."""
        if outlet_number == 1:
            dev = self.outlet1
        elif outlet_number == 2:
            dev = self.outlet2
        else:
            print(f"Invalid outlet number: {outlet_number}. Must be 1 or 2.", file=sys.stderr)
            return False

        if dev is None:
            print("Outlet device not initialized.", file=sys.stderr)
            return False

        if not isinstance(state, bool):
            print(f"Invalid state value: {state!r}. Expected boolean.", file=sys.stderr)
            return False

        try:
            dev.value = state
            print(f"Outlet {outlet_number} set to {'ON' if state else 'OFF'}")
            return True
        except DeviceClosed:
            print(f"Attempted to write to closed device for outlet {outlet_number}.", file=sys.stderr)
            return False
        except GPIOZeroError as exc:
            print(f"GPIO error setting outlet {outlet_number}: {exc}", file=sys.stderr)
            return False

    def read_outlet_state(self, outlet_number: int) -> bool | None:
        """Read the current logical state of an outlet. Returns None on error/invalid."""
        if outlet_number == 1:
            dev = self.outlet1
        elif outlet_number == 2:
            dev = self.outlet2
        else:
            print(f"Invalid outlet number: {outlet_number}. Must be 1 or 2.", file=sys.stderr)
            return None

        if dev is None:
            print("Outlet device not initialized.", file=sys.stderr)
            return None

        try:
            return bool(dev.value)
        except DeviceClosed:
            print(f"Attempted to read from closed device for outlet {outlet_number}.", file=sys.stderr)
            return None
        except GPIOZeroError as exc:
            print(f"GPIO error reading outlet {outlet_number}: {exc}", file=sys.stderr)
            return None

    def close(self):
        """Release both GPIO devices cleanly."""
        for name, dev in (("outlet1", self.outlet1), ("outlet2", self.outlet2)):
            if dev is not None:
                try:
                    dev.close()
                except Exception as exc:  # noqa: BLE001 - best-effort cleanup
                    print(f"Warning while closing {name}: {exc}", file=sys.stderr)


def main():
    controller = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = SmartOutletsController(OUTLET_1_PIN, OUTLET_2_PIN)
    except GPIOZeroError:
        sys.exit(1)

    try:
        while not shutting_down:
            for outlet_num in (1, 2):
                if shutting_down:
                    break
                state = controller.read_outlet_state(outlet_num)
                if state is None:
                    print(f"Skipping invalid read for outlet {outlet_num}.")
                else:
                    print(f"Outlet {outlet_num} state: {'ON' if state else 'OFF'}")

            if shutting_down:
                break

            time.sleep(POLL_INTERVAL_S)
    finally:
        if controller is not None:
            controller.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys

from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

SERIAL_PORT = "/dev/i2c-1"
I2C_ADDRESS = 0x3C
UPDATE_INTERVAL_SECONDS = 5


class DisplayManager:
    """Manages the SSD1306 OLED display lifecycle and rendering."""

    def __init__(self, serial_port: str, address: int):
        self.serial = None
        self.device = None
        try:
            self.serial = i2c(port=serial_port, address=address)
            self.device = ssd1306(self.serial)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize SSD1306 at {hex(address)}: {e}") from e

    def render_text(self, text: str) -> None:
        with canvas(self.device) as draw:
            draw.text((0, 0), text, fill="white")

    def close(self) -> None:
        if self.device is not None:
            try:
                self.device.cleanup()
            except Exception:
                pass
            self.device = None
        if self.serial is not None:
            try:
                self.serial.cleanup()
            except Exception:
                pass
            self.serial = None


def main() -> int:
    manager = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        manager = DisplayManager(SERIAL_PORT, I2C_ADDRESS)
    except RuntimeError as e:
        print(f"Error initializing display: {e}", file=sys.stderr)
        return 1

    try:
        while not shutting_down:
            current_time = time.strftime("%H:%M:%S")
            date_string = time.strftime("%d-%m-%Y")
            status_message = "System OK"

            try:
                manager.render_text(
                    f"{date_string}\n{current_time}\n{status_message}"
                )
            except Exception as e:
                print(f"Display write failed: {e}", file=sys.stderr)
                break

            # Sleep in small increments so signals are caught promptly
            elapsed = 0.0
            while elapsed < UPDATE_INTERVAL_SECONDS and not shutting_down:
                time.sleep(0.1)
                elapsed += 0.1

    finally:
        if manager is not None:
            manager.close()

    return 0 if not shutting_down else 130


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from gpiozero import PWMOutputDevice

# BCM pin numbers
PWM_PINS = [4, 17]
UPDATE_INTERVAL_S = 0.5


def validate(value: float) -> bool:
    """Validate that a PWM value is within the valid range."""
    return -1.0 <= value <= 1.0


def main() -> int:
    pwm_devices = []
    try:
        # Initialize PWM outputs with initial duty cycle of 0
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin=pin, initial_value=0.0)
            pwm_devices.append(dev)

        print("Starting PWM control loop. Press Ctrl+C to stop.")

        while True:
            for i, dev in enumerate(pwm_devices):
                raw = input(f"Enter PWM value for pin {PWM_PINS[i]} (-1.0 to 1.0): ").strip()
                try:
                    val = float(raw)
                except ValueError:
                    print(f"Invalid input '{raw}' for pin {PWM_PINS[i]}; skipping this iteration.")
                    continue

                if not validate(val):
                    print(
                        f"PWM value {val} out of range for pin {PWM_PINS[i]}. "
                        "Value must be between -1.0 and 1.0."
                    )
                    continue

                dev.value = val
                print(f"Pin {PWM_PINS[i]} set to {val}")

            time.sleep(UPDATE_INTERVAL_S)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release hardware resources cleanly
        for dev in pwm_devices:
            try:
                dev.close()
            except Exception as exc:
