import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
EXPECTED_WHO_AM_I = 0x68

running = True


def _handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

try:
    bus = SMBus(1)
except OSError as exc:
    print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
    sys.exit(1)


def read_byte(reg):
    try:
        return bus.read_byte_data(MPU6050_ADDR, reg)
    except OSError as exc:
        raise RuntimeError(f"I2C read failed at register 0x{reg:02X}: {exc}") from exc


def write_byte(reg, value):
    try:
        bus.write_byte_data(MPU6050_ADDR, reg, value)
    except OSError as exc:
        raise RuntimeError(f"I2C write failed at register 0x{reg:02X}: {exc}") from exc


def verify_device():
    who = read_byte(WHO_AM_I)
    if who != EXPECTED_WHO_AM_I:
        raise RuntimeError(
            f"Device WHO_AM_I mismatch: got 0x{who:02X}, expected 0x{EXPECTED_WHO_AM_I:02X}"
        )


def main():
    try:
        verify_device()
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        write_byte(PWR_MGMT_1, 0x00)  # wake up sensor
    except RuntimeError as exc:
        print(f"Warning: could not power-on reset: {exc}", file=sys.stderr)

    readings_taken = 0
    try:
        while running and readings_taken < 5:
            try:
                data = bus.read_i2c_block_data(MPU6050_ADDR, 0x3B, 14)
            except OSError as exc:
                print(f"Error: I2C block read failed: {exc}", file=sys.stderr)
                break

            gyro_x = int.from_bytes(data[2:4], "little", signed=True)
            gyro_y = int.from_bytes(data[4:6], "little", signed=True)
            gyro_z = int.from_bytes(data[6:8], "little", signed=True)
            accel_x = int.from_bytes(data[0:2], "little", signed=True)
            accel_y = int.from_bytes(data[8:10], "little", signed=True)
            accel_z = int.from_bytes(data[10:12], "little", signed=True)

            print(
                f"Gyro X={gyro_x} Y={gyro_y} Z={gyro_z} "
                f"Accel X={accel_x} Y={accel_y} Z={accel_z}"
            )
            readings_taken += 1

            if running and readings_taken < 5:
                time.sleep(0.1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys

try:
    import board
    import adafruit_dht
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-dht", file=sys.stderr)
    sys.exit(1)

DHT_PIN = board.D17
READ_INTERVAL_S = 0.5
NUM_CYCLES = 5


class GracefulExit:
    def __init__(self):
        self.received = False
        signal.signal(signal.SIGINT, self._handler)
        signal.signal(signal.SIGTERM, self._handler)

    def _handler(self, signum, frame):
        self.received = True

    def should_exit(self):
        return self.received


def main():
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on GPIO 17: {e}", file=sys.stderr)
        sys.exit(1)

    exit_flag = GracefulExit()

    try:
        for i in range(NUM_CYCLES):
            if exit_flag.should_exit():
                break

            try:
                temperature_c = dht_device.temperature
                humidity_percent = dht_device.humidity

                if temperature_c is not None and humidity_percent is not None:
                    print(
                        f"[{i + 1}/{NUM_CYCLES}] "
                        f"Temperature: {temperature_c:.1f} C | "
                        f"Humidity: {humidity_percent:.1f} %"
                    )
                else:
                    print(
                        f"[{i + 1}/{NUM_CYCLES}] "
                        "Sensor returned None — check wiring or sensor presence."
                    )

            except RuntimeError as re:
                # Common transient DHT read failures (checksum, timeout)
                print(
                    f"[{i + 1}/{NUM_CYCLES}] Read error: {re}",
                    file=sys.stderr,
                )
            except Exception as e:
                print(
                    f"[{i + 1}/{NUM_CYCLES}] Unexpected error: {e}",
                    file=sys.stderr,
                )

            if i < NUM_CYCLES - 1 and not exit_flag.should_exit():
                time.sleep(READ_INTERVAL_S)

    finally:
        try:
            dht_device.exit()
        except Exception:
            pass
        if exit_flag.should_exit():
            print("\nInterrupted by signal.", file=sys.stderr)
            sys.exit(130)


if __name__ == "__main__":
    main()

