from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
PWM_PIN_1 = 15
PWM_PIN_2 = 18


def main() -> int:
    pwm_devices: list[PWMOutputDevice] = []

    def cleanup(*args):
        for dev in pwm_devices:
            try:
                dev.close()
            except DeviceClosed:
                pass
            except Exception as exc:
                print(f"Warning: error closing PWM device: {exc}", file=sys.stderr)
        sys.exit(0)

    # Graceful shutdown on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        pwm_devices.append(PWMOutputDevice(PWM_PIN_1))
        pwm_devices.append(PWMOutputDevice(PWM_PIN_2))

        # Drive both pins at ~50 % duty cycle
        for idx, dev in enumerate(pwm_devices, start=1):
            dev.value = 0.50
            print(f"PWM pin GPIO{dev.pin.number} set to 50%")

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1

    # Hold briefly so the state is observable before exiting
    try:
        while True:
            signal.pause()
    except KeyboardInterrupt:
        cleanup()


if __name__ == "__main__":
    sys.exit(main())

import signal
