import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin numbers
OUT_PINS = [0, 17]
INTERVAL_S = 0.5


def main() -> int:
    # Create outputs; gpiozero raises GPIOZeroError if the pin cannot be claimed.
    try:
        outs = [DigitalOutputDevice(pin) for pin in OUT_PINS]
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        return 1

    def cleanup(*_args):
        """Release every output so underlying GPIO lines are released."""
        for out in outs:
            try:
                out.close()
            except Exception:
                pass
        sys.exit(0)

    # Graceful shutdown on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while True:
            values = []
            for out in outs:
                try:
                    val = bool(out.value)
                except GPIOZeroError as exc:
                    print(f"Read error on pin {out.pin}: {exc}", file=sys.stderr)
                    val = None
                values.append(val)

            if all(v is not None for v in values):
                print("Current Values:", " | ".join(str(v) for v in values))
            else:
                print("Skipping invalid read cycle", file=sys.stderr)

            time.sleep(INTERVAL_S)
    finally:
        cleanup()


