    sys.exit(main())

import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Continuously capture images from the Raspberry Pi camera."""

    def __init__(self):
        self.camera = None
        self._running = True

    # ------------------------------------------------------------------
    # Setup / teardown
    # ------------------------------------------------------------------
    def setup(self) -> bool:
        """Initialise the camera. Returns False if the device is absent."""
        try:
            self.camera = Picamera2()
            still_config = self.camera.create_still_configuration(
                main={"size": (640, 480)}
            )
            self.camera.configure(still_config)
            self.camera.start()
            return True
        except Exception as exc:
            print(f"Error: failed to initialise camera — {exc}", file=sys.stderr)
            self.camera = None
            return False

    def cleanup(self) -> None:
        """Release the camera resource safely."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
            finally:
                self.camera = None

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self) -> int:
        """Capture one frame per 0.01 s until interrupted or fatal error.

        Returns a process exit code.
        """
        if not self.setup():
            return 1

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            while self._running:
                try:
                    metadata = self.camera.capture_file("image.jpg")
                    timestamp_ms = metadata.get("timestamp", -1)
                    if timestamp_ms < 0:
                        print("Warning: missing timestamp in metadata",
                              file=sys.stderr)
                    else:
                        print(f"Image saved at {timestamp_ms} ms")
                except Exception as exc:
                    print(f"Error capturing image: {exc}", file=sys.stderr)
                    break

                time.sleep(0.01)
        finally:
            self.cleanup()

        return 0

    def _signal_handler(self, signum, frame) -> None:
        """Set the running flag to False so the main loop exits cleanly."""
        self._running = False


if __name__ == "__main__":
    app = CameraApp()
    sys.exit(app.run())

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PINS = [4, 12, 23, 24, 25, 27]
UPDATE_INTERVAL_S = 2.0


class PWMController:
    """Manages PWM outputs on specified BCM pins with clean shutdown."""

    def __init__(self, pins):
        self.pins = list(pins)
        self.devices = []
        try:
            for pin in self.pins:
                dev = PWMOutputDevice(pin=pin, initial_value=0.0, frequency=100)
                self.devices.append(dev)
        except GPIOZeroError as exc:
            self._cleanup()
            raise RuntimeError(f"Failed to initialize PWM devices: {exc}") from exc

    def set_duty_cycle(self, index, duty_percent):
        """Set the duty cycle of the PWM device at *index*.

        gpiozero expects a float in [0.0, 1.0].
        """
        if not 0 <= index < len(self.devices):
            print(f"Invalid index {index}; skipping.", file=sys.stderr)
            return
        value = max(0.0, min(float(duty_percent), 100.0)) / 100.0
        try:
            self.devices[index].value = value
            print(f"GPIO{self.pins[index]} -> {duty_percent:.1f}%")
        except GPIOZeroError as exc:
            print(f"Error setting GPIO{self.pins[index]}: {exc}", file=sys.stderr)

    def update_all(self, pattern):
        """Apply one row of duty-cycle percentages."""
        for idx, pct in enumerate(pattern):
            self.set_duty_cycle(idx, pct)

    def _cleanup(self):
        for dev in getattr(self, "devices", []):
            try:
                dev.close()
            except Exception:
                pass
        self.devices.clear()

    def close(self):
        self._cleanup()


def main():
    controller = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = PWMController(PWM_PINS)
        patterns = [
            [0, 0, 0, 0, 0, 0],
            [100, 0, 0, 0, 0, 0],
            [0, 100, 0, 0, 0, 0],
            [0, 0, 100, 0, 0, 0],
            [0, 0, 0, 100, 0, 0],
            [0, 0, 0, 0, 100, 0],
            [0, 0, 0, 0, 0, 100],
            [50, 50, 50, 50, 50, 50],
        ]

        while not shutting_down:
            for pat in patterns:
                if shutting_down:
                    break
                controller.update_all(pat)
                time.sleep(UPDATE_INTERVAL_S)

    except RuntimeError as exc:
        print(f"Initialization error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.close()
        print("Cleanup complete.")


if __name__ == "__main__":
    main()

