import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Captures still images from the Raspberry Pi camera via picamera2."""

    def __init__(self):
        self.camera = None
        self._running = True

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def capture_image(self, filename="image.jpg"):
        """
        Capture a single image.

        Returns True on success, False on failure.
        """
        try:
            self.camera.capture_file(filename)
            print(f"Image saved as {filename}")
            return True
        except Exception as exc:
            print(f"Error capturing image: {exc}", file=sys.stderr)
            return False

    def run_capture_cycle(self):
        """Run one capture cycle: attempt to capture once."""
        if not self._running:
            return
        ok = self.capture_image("image.jpg")
        if not ok:
            print("Capture failed; aborting.", file=sys.stderr)
            self._running = False

    def main_loop(self):
        """Run two capture cycles, 2 s apart."""
        while self._running and len(range(2)) > 0:
            self.run_capture_cycle()
            if not self._running:
                break
            # Sleep in small increments so signals can interrupt promptly
            slept = 0
            while slept < 2 and self._running:
                time.sleep(0.1)
                slept += 0.1

    def cleanup(self):
        """Release camera resources safely."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
            try:
                self.camera.close()
            except Exception:
                pass
            self.camera = None
        print("Camera resources released.")

    def run(self):
        """Entry point: initialise, run loop, clean up."""
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            self.camera = Picamera2()
            self.camera.start()
            print("Camera initialised.")
            self.main_loop()
        finally:
            self.cleanup()


