import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
DEVICE_ADDRESS = 0x20
READ_INTERVAL_SECONDS = 0.1


class GracefulExit:
    """Context manager / signal handler for clean shutdown."""

    def __init__(self):
        self.received = False
        self._old_int = None

    def __enter__(self):
        self._old_int = signal.signal(signal.SIGINT, self)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            signal.signal(signal.SIGINT, self._old_int)
        except Exception:
            pass
        return False

    def __call__(self, signum, frame):
        self.received = True


def read_pcf8574(bus: SMBus) -> int | None:
    """
    Read one byte from the PCF8574.

    Returns the raw byte value, or None if the device is not present.
    Raises OSError on other I/O failures so the caller can abort cleanly.
    """
    write_msg = i2c_msg.write(DEVICE_ADDRESS, [])
    read_msg = i2c_msg.read(DEVICE_ADDRESS, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]


def validate_reading(value: int) -> bool:
    """Reject out-of-range values as a sanity-check guard."""
    return 0 <= value <= 0xFF


def main() -> int:
    with GracefulExit() as exit_handler:
        try:
            bus = SMBus(I2C_BUS)
        except FileNotFoundError:
            print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C via raspi-config.", file=sys.stderr)
            return 1
        except PermissionError:
            print("Error: permission denied opening I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
            return 1
        except OSError as e:
            print(f"Error: could not open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
            return 1

        try:
            # Probe the device before entering the loop.
            try:
                _ = read_pcf8574(bus)
            except OSError as e:
                print(f"Error: no device found at address 0x{DEVICE_ADDRESS:02X} on bus {I2C_BUS}. ({e})", file=sys.stderr)
                return 1

            while not exit_handler.received:
                try:
                    value = read_pcf8574(bus)
                except OSError as e:
                    print(f"Warning: I2C read failed: {e}", file=sys.stderr)
                    time.sleep(READ_INTERVAL_SECONDS)
                    continue

                if not validate_reading(value):
                    print(f"Warning: invalid reading received: {value!r}", file=sys.stderr)

                print(f"PCF8574 Reading: {value:#04x}")
                time.sleep(READ_INTERVAL_SECONDS)

        finally:
            bus.close()

    if exit_handler.received:
        print("\nInterrupted by user. Exiting gracefully.")
        return 0

    return 0


if __name__ == "__main__":
    sys.exit(main())

import time
import signal
import sys

from picamera2 import Picamera2


class CameraApp:
    """Continuously capture images from the Raspberry Pi camera at 5-second intervals."""

    def __init__(self):
        self.camera = None
        self._running = True

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}; shutting down...")
        self._running = False

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self):
        # Install signal handlers for clean shutdown
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            self.camera = Picamera2()
            still_config = self.camera.create_still_configuration(
                main={"size": (1920, 1080), "format": "RGB888"}
            )
            self.camera.configure(still_config)
            self.camera.start()

            while self._running:
                timestamp = int(time.time() * 1000)
                filename = f"image_{timestamp}.jpg"

                try:
                    metadata = self.camera.capture_file(filename)
                    print(f"Image saved: {filename}")
                except Exception as exc:
                    print(f"Error capturing/saving image: {exc}", file=sys.stderr)

                # Sleep in small increments so signals are caught promptly
                slept = 0
                while slept < 5 and self._running:
                    time.sleep(0.1)
                    slept += 0.1

        except RuntimeError as exc:
            # picamera2 raises RuntimeError when the camera device cannot be opened
            print(f"Camera initialization failed: {exc}", file=sys.stderr)
            return 1
        finally:
            if self.camera is not None:
                try:
                    self.camera.stop()
                except Exception:
                    pass
                try:
                    self.camera.close()
                except Exception:
                    pass

        return 0


if __name__ == "__main__":
