import time

from gpiozero import DigitalOutputDevice

OUTPUT_PINS = [17, 18]
INTERVAL_SECONDS = 0.1


def validate_reading(reading: int) -> bool:
    """Return True if *reading* is a valid digital-output value."""
    return isinstance(reading, int) and reading in (0, 1)


def main() -> None:
    outputs = []
    try:
        for pin in OUTPUT_PINS:
            out = DigitalOutputDevice(pin)
            outputs.append(out)

        def cleanup(signum=None, frame=None):
            for out in outputs:
                try:
                    out.close()
                except Exception:
                    pass
            if signum is not None:
                sys.exit(0)

        signal.signal(signal.SIGINT, cleanup)
        signal.signal(signal.SIGTERM, cleanup)

        while True:
            readings = [int(i % 2) for i in range(len(outputs))]
            for out, val in zip(outputs, readings):
                if validate_reading(val):
                    out.value = val
                    print(f"GPIO{out.pin.number} set to {val}")
                else:
                    print(
                        f"Invalid reading {val!r}; skipping update",
                        file=sys.stderr,
                    )
            time.sleep(INTERVAL_SECONDS)

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        raise


