import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

TRIGGER_PIN = 17
ECHO_PIN = 18
MAX_DISTANCE_METERS = 1.0   # 1 m is well within the HC-SR04's range (~4 m typical)
CYCLES = 10
DELAY_SECONDS = 0.1


def main() -> int:
    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_METERS,
        )
    except BadPinFactory as exc:
        print(f"ERROR: No pin factory available on this platform: {exc}", file=sys.stderr)
        return 1
    except GPIOZeroError as exc:
        print(f"ERROR: Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        return 1

    def shutdown(signum=None, frame=None):
        sensor.close()
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)

    readings_taken = 0
    try:
        while readings_taken < CYCLES:
            try:
                distance_meters = sensor.distance
            except GPIOZeroError as exc:
                print(f"WARN: Read failed ({exc}); skipping cycle.", file=sys.stderr)
                time.sleep(DELAY_SECONDS)
                continue

            if distance_meters is None or distance_meters <= 0:
                print("WARN: Invalid reading (no echo).", file=sys.stderr)
            else:
                print(f"Distance: {distance_meters * 100:.2f} cm")

            readings_taken += 1
            time.sleep(DELAY_SECONDS)
    finally:
        sensor.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

