import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin mapping: echo -> trigger
TRIG_ECHO_PINS = [
    (19, 20),   # sensor 0
    (24, 25),   # sensor 1
    (26, 27),   # sensor 2
]

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_distance(sensor):
    """Return distance in cm, or None if no reading could be obtained."""
    try:
        dist_m = sensor.distance
    except DeviceClosed:
        return None
    except Exception as exc:
        print(f"Warning: read error on sensor {sensor}: {exc}", file=sys.stderr)
        return None
    if dist_m is None:
        return None
    return round(dist_m * 100.0, 2)


def main():
    global _running

    sensors = []
    for trig_pin, echo_pin in TRIG_ECHO_PINS:
        try:
            s = DistanceSensor(echo=echo_pin, trigger=trig_pin,
