        except GPIOZeroError as exc:
            print(f"Failed to initialise sensor on trig={trig_pin}, "
                  f"echo={echo_pin}: {exc}", file=sys.stderr)
            sys.exit(1)

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        while _running:
            readings = [read_distance(s) for s in sensors]
            states = ["OK" if d is not None else "NO" for d in readings]
            parts = []
            for idx, state in enumerate(states):
                name = f"s{idx}"
                parts.append(f"{name}={state}")
            print(" | ".join(parts))
            time.sleep(1)
    finally:
        for s in sensors:
            try:
                s.close()
            except Exception:
                pass
        print("\nGPIO cleanup done.")


