import time
import signal
import sys

from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

SERIAL_PORT = "/dev/i2c-1"
I2C_ADDRESS = 0x3C
UPDATE_INTERVAL_SECONDS = 0.1


def initialize_display():
    """Initialize the SSD1306 OLED display over I2C."""
    try:
        serial_interface = i2c(port=1, address=I2C_ADDRESS)
        return ssd1306(serial_interface)
    except Exception as e:
        print(f"Error initializing display: {e}", file=sys.stderr)
        return None


def render_value(device, value):
    """Render a single numeric value onto the display."""
    with canvas(device) as draw:
        draw.text((0, 0), str(value), fill="white")


def main_loop(display_device):
    """Continuously update the display with incrementing values."""
    counter = 0
    while True:
        render_value(display_device, counter)
        counter += 1
        time.sleep(UPDATE_INTERVAL_SECONDS)


def main():
    display_device = initialize_display()
    if display_device is None:
        sys.exit(1)

    def shutdown(signum=None, frame=None):
        print("\nExiting...")
        try:
            display_device.cleanup()
        except Exception:
            pass
        sys.exit(0)

    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)

    try:
        main_loop(display_device)
    except KeyboardInterrupt:
        shutdown()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DigitalOutputDevice

OUTPUT_PINS = [17, 18]
INTERVAL_SECONDS = 0.2


def validate_reading(reading: int) -> bool:
    """Return True if *reading* is a valid digital-output value."""
    return isinstance(reading, int) and reading in (0, 1)


def main() -> None:
    outputs = []
    try:
        for pin in OUTPUT_PINS:
            out = DigitalOutputDevice(pin)
            outputs.append(out)

        def cleanup(signum=None, frame=None):
            for out in outputs:
                try:
                    out.close()
                except Exception:
                    pass
            if signum is not None:
                sys.exit(0)

        signal.signal(signal.SIGINT, cleanup)
        signal.signal(signal.SIGTERM, cleanup)

        while True:
            readings = [int(i % 2) for i in range(len(outputs))]
            for out, val in zip(outputs, readings):
                if validate_reading(val):
                    out.value = val
                    print(f"GPIO{out.pin.number} set to {val}")
                else:
                    print(
                        f"Invalid reading {val!r}; skipping update",
                        file=sys.stderr,
                    )
            time.sleep(INTERVAL_SECONDS)

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        raise


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pins requested by the task
PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _running

    # Install signal handlers so we can clean up on Ctrl-C or kill.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin=pin, initial_value=0.0, frequency=1000)
            devices.append(dev)
            print(f"Initialized PWM on BCM GPIO {pin} at 0.0 duty cycle")
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM devices: {exc}", file=sys.stderr)
        cleanup(devices)
        sys.exit(1)

    try:
        while _running:
            for idx, dev in enumerate(devices):
                if not _running:
                    break
                try:
                    value = float(idx % 9 - 4) / 4.0
                    # Clamp to the valid gpiozero PWM range [0.0, 1.0]
                    clamped = max(0.0, min(1.0, value))
                    dev.value = clamped
                    print(
                        f"GPIO {dev.pin.number}: "
                        f"duty cycle set to {clamped:.2f}"
                    )
                except (ValueError, DeviceClosed) as exc:
                    print(
                        f"Invalid value or device closed for GPIO "
                        f"{dev.pin.number}: {exc}",
                        file=sys.stderr,
                    )
                except GPIOZeroError as exc:
                    print(
                        f"Hardware error on GPIO {dev.pin.number}: {exc}",
                        file=sys.stderr,
                    )

            if _running:
                time.sleep(1.0)
    finally:
        cleanup(devices)


def cleanup(devices):
    """Turn off and close every PWM device, ignoring errors during teardown."""
    for dev in devices:
        try:
            dev.off()
            dev.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
PINS = [2, 17]
INTERVAL_S = 0.1


def main() -> int:
    devices: list[DigitalOutputDevice] = []
    try:
        for pin in PINS:
            dev = DigitalOutputDevice(pin)
            devices.append(dev)

        # Drive both pins HIGH initially.
        for dev in devices:
            dev.on()

        print(f"Initialized {len(PINS)} output(s): {[d.pin.number for d in devices]}")
        print("Setting outputs HIGH...")

        while True:
            for dev in devices:
                print(f"GPIO{dev.pin.number} -> HIGH", flush=True)
            time.sleep(INTERVAL_S)

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        return 130
    finally:
        for dev in devices:
            try:
                dev.close()
            except DeviceClosed:
                pass
            except Exception as exc:  # noqa: BLE001 - best-effort cleanup
                print(f"Warning during cleanup of GPIO{getattr(dev, 'pin', '?')}: {exc}",
                      file=sys.stderr)


if __name__ == "__main__":
    sys.exit(main())

