import signal
import sys
import time

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"   # Mini UART / primary UART on Raspberry Pi
BAUD_RATE = 9600
TIMEOUT_S = 5                    # Give-up timeout per read attempt
READ_INTERVAL_S = 2             # Delay between successful reads
NUM_READINGS = 3                # Total readings before exiting

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def open_serial_port():
    """Open the serial port or return None on failure."""
    try:
        conn = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1,                 # Shortest possible timeout so we can poll
        )
    except serial.SerialException as exc:
        print(f"Error opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

    if not conn.is_open:
        print(f"{SERIAL_PORT} reported closed after open.", file=sys.stderr)
        return None

    print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")
    return conn


def read_sensor_data(conn):
    """
    Attempt a single readline() from the serial link.
    Returns the stripped line string, or None if no data / timeout.
    """
    try:
        raw = conn.readline()
    except serial.SerialException as exc:
        print(f"Serial I/O error during read: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error during serial read: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None                       # Timeout — no data available yet
    return raw.decode("utf-8", errors="replace").strip()


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    conn = open_serial_port()
    if conn is None:
        sys.exit(1)

    readings_taken = 0

    try:
        while _running and readings_taken < NUM_READINGS:
            data = read_sensor_data(conn)

            if data:
                print(f"Sensor Data: {data}")
                readings_taken += 1
                if readings_taken < NUM_READINGS:
                    time.sleep(READ_INTERVAL_S)
            else:
                # No data within the short timeout — keep polling but don't wait long
                pass

    finally:
        try:
            if conn.is_open:
                conn.close()
                print("Serial port closed.")
        except Exception as exc:
            print(f"Warning: error closing serial port: {exc}", file=sys.stderr)

    if readings_taken == NUM_READINGS:
        print("Completed all readings successfully.")
        sys.exit(0)
    else:
        print("Interrupted or no response from sensor.", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers wired to each HC-SR04 trigger / echo pair.
TRIG_ECHO_PINS = [(17, 22), (22, 27), (27, 17)]

POLL_INTERVAL_S = 0.5
SENSOR_TIMEOUT_S = 0.5   # max wait per read before giving up


class HCSR04Reader:
    """Thin wrapper around gpiozero.DistanceSensor with error handling."""

    def __init__(self, trig_pin: int, echo_pin: int):
        self.trig_pin = trig_pin
        self.echo_pin = echo_pin
        try:
            self.sensor = DistanceSensor(
                echo=echo_pin,
                trigger=trig_pin,
                max_distance=4.0,          # HC-SR04 practical max ~4 m
                threshold_distance=0.02,   # 2 cm usable range
            )
        except GPIOZeroError as exc:
            raise RuntimeError(
                f"Failed to initialise HC-SR04 on trig={trig_pin} echo={echo_pin}: {exc}"
            ) from exc

    @property
    def distance_m(self) -> float | None:
        """Return distance in metres, or None if no reading could be obtained."""
        try:
            dist = self.sensor.distance
        except DeviceClosed:
            return None
        except GPIOZeroError:
            return None
        if dist is None or dist < 0 or dist > 4.0:
            return None
        return round(dist, 3)

    def close(self):
        try:
            self.sensor.close()
        except Exception:
            pass


def main() -> int:
    readers = []
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        for trig, echo in TRIG_ECHO_PINS:
            try:
                readers.append(HCSR04Reader(trig, echo))
            except RuntimeError as exc:
                print(f"[ERROR] {exc}", file=sys.stderr)
                return 1

        while not shutting_down:
            readings = []
            for idx, reader in enumerate(readers):
                dist = reader.distance_m
                if dist is None:
                    readings.append((idx, "N/A"))
                else:
                    readings.append((idx, f"{dist:.3f}m"))

            parts = ["HC-SR04 Status:"]
            for idx, value in readings:
                label = f"GPIO{TRIG_ECHO_PINS[idx][0]}_GPIO{TRIG_ECHO_PINS[idx][1]}"
                parts.append(f"  {label:<28}{value}")
            print("\n".join(parts))

            if not shutting_down:
                time.sleep(POLL_INTERVAL_S)

    finally:
        for reader in readers:
            reader.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

