import signal
import sys

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

VALID_OUTPUTS = {17, 18}
_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_output(output_pin: int, value: bool) -> None:
    """Apply *value* to *output_pin* and report the outcome."""
    if not isinstance(value, bool):
        raise ValueError(f"Invalid value type {type(value).__name__}; expected bool.")
    if output_pin not in VALID_OUTPUTS:
        raise ValueError(
            f"Invalid pin {output_pin}; valid pins: {sorted(VALID_OUTPUTS)}"
        )

    device = None
    try:
        device = DigitalOutputDevice(output_pin)
        device.value = value
        print(f"GPIO{output_pin} set to {'HIGH' if value else 'LOW'}")
    except GPIOZeroError as exc:
        print(f"Hardware error on GPIO{output_pin}: {exc}", file=sys.stderr)
        raise
    finally:
        if device is not None:
            device.close()


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        apply_output(17, True)
        apply_output(18, False)
    except ValueError as exc:
        print(f"Value error: {exc}", file=sys.stderr)
        return 2
    except GPIOZeroError:
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

try:
    import board
    import adafruit_dht
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-dht", file=sys.stderr)
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # BCM GPIO 4 (physical pin 7)
READ_CYCLES = 3            # Number of readings before exiting
RETRY_DELAY_S = 2           # Back-off between consecutive read failures

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def main() -> int:
    sensor = None
    try:
        # Initialise the DHT22 data line.
        try:
            sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        except Exception as exc:
            print(f"Failed to initialise DHT22 on GPIO 4: {exc}", file=sys.stderr)
            return 1

        completed = 0
        while _running and completed < READ_CYCLES:
            try:
                temperature_c = sensor.temperature
                humidity_pct = sensor.humidity

                if temperature_c is not None and humidity_pct is not None:
                    print(
                        f"DHT22 reading {completed + 1}/{READ_CYCLES}: "
                        f"T={temperature_c:.1f} C  H={humidity_pct:.1f} %"
                    )
                    completed += 1
                else:
                    print("Sensor returned None — skipping cycle.", file=sys.stderr)

            except RuntimeError as exc:
                # Common transient DHT errors (checksum, timeout).
                print(f"Read error ({completed + 1}/{READ_CYCLES}): {exc}", file=sys.stderr)
            except Exception as exc:
                # Unexpected error — log and continue if possible.
                print(f"Unexpected error ({completed + 1}/{READ_CYCLES}): {exc}", file=sys.stderr)

            if _running and completed < READ_CYCLES:
                time.sleep(RETRY_DELAY_S)

        if not _running:
            print("\nInterrupted by signal; exiting gracefully.")
            return 130

        print(f"\nCompleted {completed}/{READ_CYCLES} DHT22 readings.")

    finally:
        # Release the underlying pulseio or bitbangio resource cleanly.
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

